DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.export_library_source(text,uuid)'::regprocedure) INTO d;
d:=replace(d,'''summary_en'',e.summary_en','''summaryEn'',coalesce(e.summary_en,'''')'); d:=replace(d,'''summary_es'',e.summary_es','''summaryEs'',coalesce(e.summary_es,'''')'); d:=replace(d,'''map_url'',e.map_url','''mapUrl'',coalesce(e.map_url,'''')'); d:=replace(d,'''waitlist_enabled'',e.waitlist_enabled','''waitlist'',e.waitlist_enabled'); d:=replace(d,'''tags'',e.tags','''tagsInput'',array_to_string(e.tags,'', '')'); d:=replace(d,'''accessibility_notes'',e.accessibility_notes','''accessibility'',coalesce(e.accessibility_notes,'''')'); d:=replace(d,'''what_to_bring'',e.what_to_bring','''bring'',coalesce(e.what_to_bring,'''')'); d:=replace(d,'''cancellation_policy'',e.cancellation_policy','''cancellation'',coalesce(e.cancellation_policy,'''')'); d:=replace(d,'''min_age'',e.min_age','''minAge'',coalesce(e.min_age::text,'''')'); d:=replace(d,'''ticket_tiers'',coalesce','''tiers'',coalesce'); d:=replace(d,'''price'',coalesce(e.price_cents,0)/100.0','''price'',(coalesce(e.price_cents,0)/100.0)::text'); d:=replace(d,'''place'',e.format','''place'',e.format,''url'','''',''full'',true'); d:=replace(d,'''language'',e.language','''language'',e.language,''regOpens'','''',''regCloses'','''',''contactEmail'','''',''contactPhone'','''',''allowsMinors'',false'); EXECUTE d; END $$;
COMMENT ON COLUMN public.templates.event_setup IS 'Reusable allowlisted event builder configuration only. No participants, tokens, transactions, attendance, messages, schedules or private uploaded paths.';
CREATE OR REPLACE FUNCTION public.can_use_team_templates(_team uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE up AS (SELECT m.team_id id,0 depth FROM team_members m WHERE m.user_id=auth.uid() AND m.suspended_at IS NULL AND public.team_channel_access(m.team_id) UNION ALL SELECT t.parent_team_id,up.depth+1 FROM teams t JOIN up ON t.id=up.id WHERE t.parent_team_id IS NOT NULL AND up.depth<20) SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM up WHERE up.id=_team) $$;